// Convenience keys for the common cases.
inline const std::string& forParam(const std::string& table, const std::string& param)
    { return forKey(table + "|" + param); }
inline const std::string& forEffect(const std::string& abbr)
    { return forKey(std::string("FX|") + abbr); }

// Effect slot tooltip with context disambiguation, most specific first:
//   FX|<effectName>|<abbr>   (per-program override, e.g. COMP+DIST+DLY|DELAY)
//   FX|<abbr>@<disp>         (by display-type id, e.g. R.DEL@2 vs R.DEL@6)
//   FX|<abbr>                (generic)
inline const std::string& forEffectSlot(const std::string& effectName,
                                        const std::string& abbr, int disp)
{
    const std::string& a = forKey("FX|" + effectName + "|" + abbr);
    if (! a.empty()) return a;
    const std::string& b = forKey("FX|" + abbr + "@" + std::to_string(disp));
    if (! b.empty()) return b;
    return forKey("FX|" + abbr);
}

